package com.example.data

import org.json.*

data class ChantalNpcProfile(val key: String, val name: String, val habit: String, val concern: String, val invitation: String, val replies: List<Pair<String, String>>)
object ChantalLivingWorld {
    val profiles = listOf(
        ChantalNpcProfile("Брамбл", "Брамбл", "Раскладывает травы по запаху; ворчит, если торопят, но терпелив с новичками.", "Хочет починить сушилку для трав. Не всякая встреча должна быть об этом.", "Брамбл зовёт разобрать коробку пахучих трав. Говорит, что нужен помощник с хорошим носом. Я уже дважды чихнула. Квалификация подтверждена!", listOf(
            "Выбрать травы по запаху" to "Я нашла мяту. Потом ещё мяту. Потом оказалось, что я всё время нюхала один и тот же пучок. Брамбл молча повернул коробку. Вот теперь дело пошло!",
            "Попросить Брамбла показать" to "Он дал мне листок, потом второй. Я наконец различила запахи и сама нашла нужный пучок. Брамбл кивнул. Я чуть не лопнула от гордости.",
            "Сначала устроить перерыв" to "Мы сели у двери. Брамбл принёс воду, я — свой хвост. Потом вместе разобрали половину коробки. Вторую оставили на другой раз.")),
        ChantalNpcProfile("Корвус", "Корвус", "Хвастается знанием дорог, прячет смущение за шутками; не умеет петь чисто.", "Хочет придумать удобную сумку для писем. Уважает удачные шутки и соблюдает чужие секреты.", "Корвус принёс пустой конверт и предложил нарисовать марку. Я спросила, можно ли мой портрет. Он сказал, что конверт маленький. Нахал!", listOf(
            "Нарисовать Шанталь с огромными ушами" to "Я нарисовала два уха. Место закончилось. Корвус признал портрет удивительно точным. Я решила считать это комплиментом.",
            "Изобразить самого Корвуса" to "На рисунке получилась картошка с клювом. Корвус долго молчал. Потом попросил вторую такую марку для личной коллекции.",
            "Придумать общий герб" to "Крыло, лапа и кривой кружочек. Это печенье. Корвус одобрил: на серьёзном гербе обязательно должно быть что-нибудь важное.")),
        ChantalNpcProfile("Марта", "Марта", "Говорит прямо, смеётся коротко, считает хорошую еду лучшим поводом посидеть вместе.", "Пробует новые формы булочек; иногда устает от шума мельницы и хочет тишины.", "Марта разрешила придумать форму булочки. Я предложила лису. Она выдала кусочек теста. Пока у меня получается довольно убедительная лужа.", listOf(
            "Добавить лисе уши" to "Уши выросли, хвост отвалился. Марта испекла всё отдельно. Мы съели лису по частям. Жутковато звучит, но вкусно!",
            "Сделать простую круглую булочку" to "Я скатала шарик. Марта поставила рядом свой. Мой был кривее, зато я точно знала, который мой. Он получился хороший.",
            "Назвать её волшебной лужей" to "Марта подписала дощечку: «Лужа, одна штука». После печи лужа стала пухлой. Магия сработала. Я потребовала записать рецепт.")),
        ChantalNpcProfile("Хьюго", "Хьюго", "Немногословен; чинит мелочи во время разговора и смеётся прежде всего глазами.", "Собирает удобные узлы для лодки. Не проверяй дружбу опасными испытаниями.", "Хьюго показал мне верёвку и попросил придумать название узлу. Я ещё не видела узел, но название уже придумала: «Не распускайся, пожалуйста». Он сказал, что практично.", listOf(
            "Попробовать завязать узел вместе" to "Он держал один конец, я тянула другой. Получилось! Я даже развязала его сама. Хьюго сказал, что это особенно полезная часть умения.",
            "Попросить показать медленно" to "Хьюго показал ещё раз. Я перестала торопиться и поняла, куда прячется конец верёвки. Оказывается, он не исчезал. Это я его теряла.",
            "Придумать узлу смешное имя" to "Мы назвали его «Хвост после дождя». Верёвка обидеться не смогла, а Хьюго всё-таки засмеялся вслух."))
    )
    fun profile(name: String) = profiles.firstOrNull { name.contains(it.key, ignoreCase = true) }
    private val themes = listOf("проделка", "неловкая встреча", "полезное открытие", "простая магическая неожиданность", "тёплая помощь", "маленькая неудача с хорошим выходом", "случайное знакомство")
    fun theme(memory: JSONObject, journey: Int): String {
        val events = memory.getJSONArray("events")
        val recent = (maxOf(0, events.length()-3) until events.length()).map { events.getJSONObject(it).optString("themeRu") }.toSet()
        val available = themes.filter { it !in recent }
        return available[Math.floorMod(journey, available.size)]
    }
    fun direction(memory: JSONObject, npc: String, journey: Int): JSONObject {
        val p = profile(npc)
        return JSONObject().put("themeRu", theme(memory, journey)).put("npcProfileRu", p?.let { "${it.name}: ${it.habit} ${it.concern}" } ?: "Новый персонаж: дай одну узнаваемую привычку, не перегружай биографией.")
    }
}
